        out=[];s=0
        for p in seps+[n]:
            if p>s: out.append((s,p))
            s=p+1
        return out
    rs=spans(h,sep_rows); cs=spans(w,sep_cols)
    pat=None
    for r0,r1 in rs:
        for c0,c1 in cs:
            sub=[row[c0:c1] for row in g[r0:r1]]
