def regions(grid, sep_color=None, bg=None):
    """Spans (start, end) of rows and columns between separator lines of a color other than bg."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for r in grid for v in r).most_common(1)[0][0] if bg is None else bg
    sr = [i for i in range(h) if len(set(grid[i])) == 1 and grid[i][0] != bg]
