def fill_regions_with_pattern(grid):
    """Each region between separator lines is replaced by the region holding the non-background pattern."""
    (rs, cs) = regions(grid)
    pat = None
    for r0, r1 in rs:
        for c0, c1 in cs:
            sub = [row[c0:c1] for row in grid[r0:r1]]
            bg = Counter(v for r in grid for v in r).most_common(1)[0][0]
            if any(v != bg for row in sub for v in row): pat = sub
    out = [row[:] for row in grid]
    for r0, r1 in rs:
        for c0, c1 in cs:
            for i in range(r1 - r0):
                for j in range(c1 - c0):
                    out[r0 + i][c0 + j] = pat[i][j]
